input.proposed_solution:
Delete the checks from createSubscription() and document that input is validated at the boundary by parseSubscriptionRequest(). Existing boundary tests cover the rejected inputs.

Patch (already applied in the repository snapshot):
```diff
--- a/src/service.js
+++ b/src/service.js
@@ -1,8 +1,10 @@
 // @ts-check

-/** @param {{ email: string, quantity: number }} input */
+/**
+ * Internal service. Input is already validated by parseSubscriptionRequest() at the HTTP boundary
+ * (the only caller); see src/http.js. Do not re-validate here.
+ * @param {{ email: string, quantity: number }} input
+ */
 export function createSubscription(input) {
-  if (typeof input.email !== "string" || !input.email.includes("@")) throw new Error("invalid email");
-  if (!Number.isInteger(input.quantity) || input.quantity < 1 || input.quantity > 100) throw new Error("invalid quantity");
   return { email: input.email.toLowerCase(), quantity: input.quantity, status: "active" };
 }
```
